  FT["PH-H8384"] = {"id":"PH-H8384","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_9926_2010.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将南哥打巴托省 Banga 市镇 San Jose 描笼涯的 Banga 国立中学附属校分离，改设为独立的 San Jose 国立中学，并为此拨款","en":"An Act Separating the Banga National High School - San Jose Annex in Barangay San Jose, Municipality of Banga, Province of South Cotabato from the Banga National High School, Converting it into an Independent National High School to Be Known as San Jose National High School and Appropriatng Funds Therefor","orig":"An Act Separating the Banga National High School - San Jose Annex in Barangay San Jose, Municipality of Banga, Province of South Cotabato from the Banga National High School, Converting it into an Independent National High School to Be Known as San Jose National High School and Appropriatng Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9926","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-01-07","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_9926_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8384-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. - The Banga National High School - San Jose Annex in Barangay San Jose, Municipality of Banga, Province of South Cotabato is hereby separated from the Banga National High School and converted into an independent national high school to be known as San Jose National High School."}},{"id":"PH-H8384-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Banga National High School - San Jose Annex are hereby transferred to and absorbed by the San Jose National High School."}},{"id":"PH-H8384-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization of the San Jose National High School, the initial funding of which shall be charged against the current year's appropriations of the Banga National High School - San Jose Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8384-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8384-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p119","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Banga National High School - San Jose Annex in Barangay San Jose, Municipality of Banga, Province of South Cotabato from the Banga National High School, Converting it into an Independent National High School to Be Known as San Jose National High School and Appropriatng Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
